#!/usr/bin/env bash
# PreToolUse(Edit|Write): generated files are outputs — send Claude to the source instead.
set -euo pipefail
f=$(jq -r '.tool_input.file_path // empty')
case "$f" in
  *_templ.go)
    echo "Blocked: $f is generated by templ. Edit the matching .templ file; the format hook regenerates it." >&2
    exit 2 ;;
  */internal/adapters/postgres/db/*.go)
    echo "Blocked: $f is generated by sqlc. Edit internal/adapters/postgres/*.sql and run 'make sqlc'." >&2
    exit 2 ;;
  */.env|*/.env.local)
    echo "Blocked: .env holds secrets and is never edited by Claude. Document new variables in .env.example." >&2
    exit 2 ;;
esac
exit 0
